  const sumOf = (k) => {
    const count = Math.floor(n / k);
    return k * count * (count + 1) / 2;
  };

  let total = sumOf(3) + sumOf(5) + sumOf(7);
  total -= sumOf(15) + sumOf(21) + sumOf(35);
  total += sumOf(105);
  return total;
}

